  success: "#80c340",
  /** Site tint: a section background a step above black. */
  nearBlack: "#0a0a08",
  /** Site tint: a section background a step below white. */
  paper: "#f7f7f5",
  /** Site tint: a second surface step on white. */
  paper2: "#f2f2ef",
  /** Site tint: body copy on light surfaces. */
  bodyOnLight: "#3f3f3c",
