  /** Site tint: the CTA yellow lifted, for the primary button's hover. */
  ctaYellowLight: "#f5ff4d",
  /** Site tint: the CTA yellow as text on white, which yellow itself never is. */
  ctaYellowOnLight: "#606a00",
